{"predictors": [
  {
    "name": "Patent Novelty",
    "construction": "Count of a firm's US patents in the past year, weighted by the number of forward citations received within the same period.",
    "rationale": "Innovative firms with groundbreaking inventions may outperform in the future.",
    "higher_returns_for": "High values of the measure"
  },
  {
    "name": "CEO Age",
    "construction": "Current age of the firm's CEO.",
    "rationale": "Younger CEOs may be more dynamic and innovative, leading to higher future returns.",
    "higher_returns_for": "Low values of the measure"
  },
  {
    "name": "Customer Satisfaction Index",
    "construction": "Average customer satisfaction scores from independent surveys, normalized across all companies.",
    "rationale": "Firms providing superior customer satisfaction may have a competitive advantage resulting in higher future returns.",
    "higher_returns_for": "High values of the measure"
  },
  {
    "name": "Social Media Sentiment",
    "construction": "Average sentiment score of a firm's mentions on various social media platforms over the past quarter.",
    "rationale": "Positive social media sentiment may indicate strong customer relationships and brand image, which could drive future outperformance.",
    "higher_returns_for": "High values of the measure"
  },
  {
    "name": "Employee Turnover Rate",
    "construction": "Number of employees who left the firm in the past year divided by the average number of employees during the year.",
    "rationale": "High employee turnover may be a sign of internal issues and could predict lower future performance.",
    "higher_returns_for": "Low values of the measure"
  },
  {
    "name": "Product Recall Frequency",
    "construction": "Number of product recalls in the last three years, normalized by the number of products the firm has on the market.",
    "rationale": "Frequent product recalls may indicate quality control problems, which could impact future returns negatively.",
    "higher_returns_for": "Low values of the measure"
  },
  {
    "name": "Proportion of Independent Board Members",
    "construction": "Number of independent board members divided by the total number of board members.",
    "rationale": "A higher proportion of independent board members may lead to better governance and higher future returns.",
    "higher_returns_for": "High values of the measure"
  },
  {
    "name": "Customer Concentration",
    "construction": "Sales to the firm's largest customer divided by total sales.",
    "rationale": "Firms reliant on a single customer may face higher business risks and lower future returns.",
    "higher_returns_for": "Low values of the measure"
  },
  {
    "name": "Supplier Concentration",
    "construction": "Purchases from the firm's largest supplier divided by total purchases.",
    "rationale": "High supplier concentration may indicate a lack of bargaining power, potentially leading to lower future profitability and returns.",
    "higher_returns_for": "Low values of the measure"
  },
  {
    "name": "Managerial Ownership Change",
    "construction": "Calculate the year-over-year change in the percentage of the firm's shares owned by its managers.",
    "rationale": "Increases in managerial ownership may align interests with shareholders, potentially leading to higher future returns.",
    "higher_returns_for": "High values of the measure"
  }
]}
